// thrFieldsX64 returns the x86_64 Thread field map for a given Dart version.
func thrFieldsX64(dartVersion string) map[int]string {
	// PHASE 6: check non-compressed tables first (Dart 2.x)
	if t := thrFieldsX64Nocompress(dartVersion); t != nil {
		return t
	}
	switch dartVersion {
	case "2.14.0":
		return thrV2140_x64
	case "2.15.0":
		return thrV2150_x64
	case "2.16.0":
		return thrV2160_x64
	case "2.17.6":
		return thrV2176_x64
	case "2.18.0":
		return thrV2180_x64
	case "2.19.0":
		return thrV2190_x64
	case "3.0.5":
		return thrV305_x64
	case "3.1.0":
		return thrV310_x64
	case "3.2.5", "3.3.0":
		return thrV325_x64
	// 3.5.0 has its OWN table, and used to be aliased to 3.4.3's.
	//
	// thread.h @3.5.0 adds shared_field_table_values (absent at 3.4.3,
	// verified via gh api), which lands at 0x70 and shifts every field
	// after it by one slot. The two tables differ in 108 of ~124 entries,
	// so a 3.5.0 x64 binary was getting 3.4.3's names: object_null
	// reported where the field is shared_field_table_values, bool_true
	// where object_null is, and so on down the whole struct. Not a
	// missing annotation -- a confidently wrong one at every Thread
	// access on that version.
	//
	// thrV350_x64 was written and then never wired in. Nothing caught it
	// because there is no SDK drift gate for thread FIELD offsets (only
	// for stubs, stub names and runtime entries); staticcheck found it as
	// an unused variable.
	case "3.4.3":
		return thrV343_x64
	case "3.5.0":
		return thrV350_x64
	case "3.6.2":
		return thrV362_x64
	case "3.7.0":
		return thrV370_x64
	case "3.8.1":
		return thrV381_x64
	case "3.9.2":
		return thrV392_x64
	case "3.10.7":
		return thrV3107_x64
	case "3.11.0":
		return thrV3110_x64
	case "3.12.0-dev", "3.12.2":
		return thrV3122_x64
	case "3.13.0":
		return thrV3130_x64
	}
	return nil
}

