// thrFieldsX64Nocompress returns x86_64 non-compressed THR tables for Dart 2.x.
func thrFieldsX64Nocompress(dartVersion string) map[int]string {
	switch dartVersion {
	case "2.10.0":
		return thrV2100_x64_nocompress
	case "2.12.0":
		return thrV2120_x64_nocompress
	case "2.13.0":
		return thrV2130_x64_nocompress
	case "2.14.0":
		return thrV2140_x64_nocompress
	case "2.15.0":
		return thrV2150_x64_nocompress
	case "2.16.0":
		return thrV2160_x64_nocompress
	case "2.17.6":
		return thrV2176_x64_nocompress
	}
	return nil
}

// The x64 tables carried a second init() here that merged runtime-entry
// names in at hand-written base offsets, mirroring an identical block in
// thrfields.go. Both are gone: extract_thr now derives these names from
// the SDK's own exported anchors and writes them straight into each table
// literal, for every version and both architectures.
//
// The hand-written bases had drifted a slot. runtime_offsets_extracted.h
// exports the leaf anchor on three versions, and on all three it sits at
// exit_through_ffi+8 -- one slot below where these calls placed it, so
// every leaf runtime entry they named was named as its neighbour. Only 14
// of the 27 x64 tables were listed at all; the rest rendered every
// runtime-entry call site as an unnamed THR.fNN.

